#define main e98_unused_main
#include "evaluate.cpp"
#undef main
#include "legacy/ACSG.h"

struct LegacyWorker {
 acsg_legacy::ACSG& graph;std::unique_ptr<faiss::DistanceComputer> plain;CountDC counter;faiss::VisitedTable vt;std::vector<acsg_legacy::Neighbor> ret;std::vector<acsg_legacy::EnterPoint> ep;std::array<faiss::idx_t,100> ids;
 LegacyWorker(acsg::IndexACSGFlat& idx,acsg_legacy::ACSG& g):graph(g),plain(acsg::storage_distance_computer(idx.storage)),counter(acsg::storage_distance_computer(idx.storage)),vt(idx.ntotal){ret.reserve(1501);ep.reserve(3);}
 void run(const std::string& method,Router* router,const std::vector<float>& q,size_t d,Batch& b,bool count){auto& dc=count?static_cast<faiss::DistanceComputer&>(counter):*plain;
 for(size_t i=0;i<b.n;++i){auto query=q.data()+i*d;std::array<int32_t,3> entries{-1,-1,-1};size_t k=1;if(router){entries=router->route(query);k=3;}else entries[0]=graph.enterpoint;std::copy(entries.begin(),entries.end(),b.entries.begin()+i*3);ep.clear();for(size_t j=0;j<k;++j)ep.emplace_back(entries[j],1.);vt.advance();dc.set_query(query);graph.search_new(dc,b.k,ids.data(),b.dist.data()+i*b.k,vt,2,ep,&ret);for(size_t j=0;j<b.k;++j)b.ids[i*b.k+j]=ids[j];if(count){b.graph_ndc[i]=counter.count;b.route_ndc[i]=router?router->counter.n:0;for(size_t j=0;j<k;++j)require(counter.first[j]==entries[j],"legacy entry order");}}
 }};
static void reference(const Batch& b,const fs::path& root,bool counts){require(b.ids==read_raw<int32_t>(root/"ids.i32"),"E97 ID mismatch: "+root.string());auto d=read_raw<float>(root/"distances.f32");require(d.size()==b.dist.size()&&!memcmp(d.data(),b.dist.data(),d.size()*4),"E97 distance bits mismatch");require(b.entries==read_raw<int32_t>(root/"entry_ids.i32"),"E97 entry mismatch");if(counts){require(b.route_ndc==read_raw<uint64_t>(root/"route_ndc.u64"),"E97 route NDC mismatch");require(b.graph_ndc==read_raw<uint64_t>(root/"graph_ndc.u64"),"E97 graph NDC mismatch");}}
struct Job{std::string method,kernel;};
int main(int argc,char**argv){try{require(argc==3,"benchmark config output");threads();auto c=read_json(argv[1]);fs::path out=argv[2];require(!fs::exists(out),"output must be new");fs::create_directories(out);write_json(out/"config.json",c);bool performance=c["performance"];auto idx=load_nsg(c["index"]);size_t n=c["n"],d=idx->d;require(c["threads"]==1&&c["metric_id"]==idx->metric_type,"threads/metric");Fvecs fq(c["queries"]);require(fq.n==n&&fq.d==d,"query shape");std::vector<float>q(n*d);for(size_t i=0;i<n;++i)std::copy(fq.row(i),fq.row(i)+d,q.data()+i*d);
 std::map<std::string,std::unique_ptr<Router>> routers;std::vector<std::string> methods;fs::path ref=c["reference_results"].get<std::string>();for(auto m:c["methods"]){std::string name=m["name"];if(name=="HNSW"&&!performance)continue;methods.push_back(name);if(name!="NSG"&&name!="HNSW")routers[name]=std::make_unique<Router>(m,d,ref/"k100"/(name+".hnsw"));}
 auto space=make_space(idx->metric_type,d);CountParam hc{space->get_dist_func(),space->get_dist_func_param(),0};std::unique_ptr<HNSW> full;if(performance){Fvecs base(c["base"]);full=load_topology(c["hnsw_topology"].get<std::string>(),base,space.get());}
 acsg_legacy::ACSG legacy(idx->acsg.nsg_R);legacy.ntotal=idx->acsg.ntotal;legacy.enterpoint=idx->acsg.enterpoint;legacy.is_built=true;legacy.final_graph=std::make_shared<acsg_legacy::Graph<int32_t>>(idx->acsg.final_graph->data,idx->acsg.final_graph->N,idx->acsg.final_graph->K);require(legacy.final_graph->data==idx->acsg.final_graph->data,"same adjacency memory");Worker fresh(*idx);LegacyWorker old(*idx,legacy);json progress=json::array();uint64_t calls=0;int ordinal=0;auto started=Clock::now();
 auto run=[&](const Job& j,Batch& b,bool count){Router* router=routers.count(j.method)?routers[j.method].get():nullptr;if(router)router->counting(count);if(j.method=="HNSW"){full->fstdistfunc_=count?counted:space->get_dist_func();full->dist_func_param_=count?(void*)&hc:space->get_dist_func_param();}if(j.kernel=="legacy")old.run(j.method,router,q,d,b,count);else fresh.run(j.method,router,full.get(),hc,q,d,b,count);};
 for(auto point:c["points"]){int K=point["K"],L=point["L"];require((K==1||K==100)&&L>=K&&L<=1500,"K/L");idx->acsg.search_L=legacy.search_L=L;if(full)full->setEf(L);std::vector<Job> jobs;auto ordered=methods;std::rotate(ordered.begin(),ordered.begin()+ordinal%ordered.size(),ordered.end());for(const auto& m:ordered){if(m=="HNSW")jobs.push_back({m,"reference"});else{if(performance)jobs.push_back({m,"legacy"});jobs.push_back({m,"optimized"});}}
 auto key=[&](const Job& j){return j.method+"__"+j.kernel+"_K"+std::to_string(K)+"_L"+std::to_string(L);};std::map<std::string,std::vector<double>> timings;
 if(performance)for(int rep=0;rep<3;++rep){auto order=jobs;if(rep%2)std::reverse(order.begin(),order.end());for(const auto& j:order){auto name=key(j);auto rpath=ref/("k"+std::to_string(K))/(j.method+"_L"+std::to_string(L));Batch b(n,K);if(rep==0){Batch warm(n,K);run(j,warm,false);calls+=n;reference(warm,rpath,false);}threads();auto t=Clock::now();run(j,b,false);double sec=seconds(t);calls+=n;reference(b,rpath,false);if(rep==0)save_batch(out/name,b,false);timings[name].push_back(sec);json row={{"dataset",c["dataset"]},{"method",j.method},{"kernel",j.kernel},{"K",K},{"L",L},{"repeat",rep},{"seconds",sec},{"qps",n/sec},{"n",n},{"threads",process_threads()},{"cpu",15},{"e97_bit_parity",true}};progress.push_back(row);write_json(out/"timing_progress.json",progress);std::cout<<row.dump()<<std::endl;}}
 for(const auto& j:jobs){Batch b(n,K);run(j,b,true);calls+=n;auto name=key(j);reference(b,ref/("k"+std::to_string(K))/(j.method+"_L"+std::to_string(L)),true);if(!performance)save_batch(out/name,b,false);save_batch(out/name,b,true);write_json(out/name/"complete.json",{{"status","PASS"},{"method",j.method},{"kernel",j.kernel},{"K",K},{"L",L},{"n",n},{"seconds",timings[name]},{"per_query_ndc_and_bit_output_parity",true},{"threads",1},{"cpu",15}});std::cout<<"PARITY "<<name<<std::endl;}
 ++ordinal;struct rusage r;getrusage(RUSAGE_SELF,&r);require(r.ru_maxrss<64LL*1024*1024,"RSS cap");write_json(out/"progress.json",{{"completed_points",ordinal},{"search_calls",calls},{"elapsed_seconds",seconds(started)}});}
 struct rusage r;getrusage(RUSAGE_SELF,&r);write_json(out/"complete.json",{{"status","PASS"},{"dataset",c["dataset"]},{"performance",performance},{"search_calls",calls},{"wall_rounds",progress.size()},{"maxrss_kib",r.ru_maxrss},{"seconds_excluding_load",seconds(started)},{"threads",process_threads()},{"cpu",15},{"same_loaded_adjacency_and_storage",true},{"reference_results",ref.string()}});return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
